node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get product info
const product = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-2028EE'\").all();
console.log('Product:', JSON.stringify(product, null, 2));

// Get column info for products
const cols = db.prepare(\"PRAGMA table_info(products)\").all();
console.log('\nProduct columns:', cols.map(c => c.name));

// Check rt_variants for this product
const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-2028EE'\").all();
console.log('\nVariants:', JSON.stringify(variants, null, 2));

// Also check rt_variants columns
const vcols = db.prepare(\"PRAGMA table_info(rt_variants)\").all();
console.log('\nVariant columns:', vcols.map(c => c.name));
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check if any other products list PROD-2028EE in their compatible_with_json
const compatRefs = db.prepare(\"SELECT product_id, name, compatible_with_json FROM products WHERE compatible_with_json LIKE '%PROD-2028EE%'\").all();
console.log('Products that reference PROD-2028EE as compatible:', JSON.stringify(compatRefs, null, 2));

// Check other products in same subcategory for potential related accessories
const related = db.prepare(\"SELECT product_id, name, price, compatible_with_json, description FROM products WHERE subcategory = 'Mobile Accessories'\").all();
console.log('\nAll Mobile Accessories:', JSON.stringify(related, null, 2));

// Also check if the description or specs mention compatibility
const product = db.prepare(\"SELECT specs_json, description, compatible_with_json FROM products WHERE product_id = 'PROD-2028EE'\").get();
console.log('\nProduct details:');
console.log('  specs_json:', product.specs_json);
console.log('  compatible_with_json:', product.compatible_with_json);
console.log('  description:', product.description);
"

